  'Change sign-in e-mail': 'Zmień e-mail do logowania',
  'Add a sign-in e-mail': 'Dodaj e-mail do logowania',
  'Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.': 'Wpisz go w „Zaloguj się hasłem” zamiast nazwy profilu. Nigdy nic na niego nie wysyłamy; zapomniane hasło nadal resetuje twój admin.',
  'E-mail address': 'Adres e-mail',
