  'Afterwards you sign in with your profile name only.': 'Potem logujesz się już tylko nazwą profilu.',
  'E-mail removed': 'E-mail usunięty',
  'Too many attempts. Try again {0}.': 'Za dużo prób. Spróbuj ponownie {0}.',
  'Use at least {0} characters.': 'Użyj co najmniej {0} znaków.',
  'That password is too long.': 'To hasło jest za długie.',
  'That password is too easy to guess. Try a longer one, or a few random words strung together.': 'To hasło jest zbyt łatwe do odgadnięcia. Spróbuj dłuższego albo kilku losowych słów połączonych razem.',
