  'Your passkey could not be confirmed.': 'Nie udało się potwierdzić klucza dostępu.',
  'This password is the only way into your profile, so it cannot be removed.': 'To hasło jest jedynym sposobem wejścia do twojego profilu, więc nie można go usunąć.',
