  'Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted openGym”: your server can reach an http:// model on its own network.': 'Android blokuje nieszyfrowane połączenia http:// z aplikacji, więc ten telefon połączy się tylko z punktem końcowym https://. Postaw przed nim HTTPS (Tailscale albo reverse proxy) albo wybierz „Użyj mojego własnego openGym”: twój serwer połączy się z modelem http:// we własnej sieci.',
  'Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.': 'Każde zapytanie trafia prosto do {0} z twoim kluczem. Nikt inny go nie widzi, a płacisz Ty.',
  'Endpoint': 'Endpoint',
  'Enter your API key': 'Wpisz swój klucz API',
  'Enter the endpoint URL': 'Wpisz adres URL endpointu',
  'There’s no routine to review yet. Build one with at least two exercises first.': 'Nie ma jeszcze planu treningowego do przejrzenia. Najpierw utwórz taki z co najmniej dwoma ćwiczeniami.',
  'How should the Coach run?': 'Jak ma działać Trener?',
  'List models': 'Pokaż modele',
  'Model': 'Model',
  'Nothing to change right now: {0}': 'Na razie nic do zmiany: {0}',
  'Off. Choose how the Coach should run.': 'Wyłączony. Wybierz, jak ma działać Trener.',
  'Pick a model': 'Wybierz model',
  'Provider': 'Dostawca',
  'Runs on this phone with your own API key': 'Działa na tym telefonie z twoim kluczem API',
  'Runs on your openGym server': 'Działa na twoim serwerze openGym',
  'Save and use the Coach': 'Zapisz i używaj Trenera',
  'The Coach is already thinking about your training.': 'Trener już analizuje twój trening.',
  'The Coach is taking a breather. You’ve used today’s {0} runs on this phone.': 'Trener łapie oddech. Wykorzystano dzisiejsze {0} uruchomień na tym telefonie.',
  'The Coach isn’t set up on this phone.': 'Trener nie jest skonfigurowany na tym telefonie.',
  'The Coach needs your go-ahead first.': 'Trener potrzebuje najpierw twojej zgody.',
  'The key is stored in this phone’s secure storage and never leaves it except to call the provider.': 'Klucz jest przechowywany w bezpiecznej pamięci tego telefonu i opuszcza go tylko po to, by wywołać dostawcę.',
  'This phone calls the provider directly with your key. Every request is charged to your account.': 'Ten telefon łączy się z dostawcą bezpośrednio z twoim kluczem. Każde zapytanie obciąża twoje konto.',
  'Turn the Coach off on this phone': 'Wyłącz Trenera na tym telefonie',
  'Use my self-hosted openGym': 'Użyj mojego własnego openGym',
  'What leaves this phone': 'Co opuszcza ten telefon',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': 'Twój serwer nie ma włączonego Trenera. Zapytaj administratora albo użyj własnego klucza poniżej.',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': 'Twój serwer uruchamia Trenera z dostawcą ustawionym przez administratora. Z tego telefonu nie wychodzi nic nowego poza tym, co i tak jest synchronizowane.',
  'Loading the exercise catalogue…': 'Wczytywanie katalogu ćwiczeń…',
  'Checking the endpoint…': 'Sprawdzanie endpointu…',

  // --- AI Coach chat ---
  'A local model can take longer.': 'Model lokalny może potrzebować więcej czasu.',
  'All optional. The more the Coach knows, the less it guesses.': 'Wszystko opcjonalne. Im więcej Trener wie, tym mniej zgaduje.',
  'Almost there': 'Prawie gotowe',
  'Avoid: {0}': 'Unikać: {0}',
  'Before we start': 'Zanim zaczniemy',
  'Building your plan…': 'Tworzę twój plan…',
  'Discarded. Tell me what was off and I will build a different one.': 'Odrzucono. Powiedz, co było nie tak, a zbuduję inny.',
  'Done! Your plan is back to how it was before my last changes.': 'Gotowe! Twój plan wrócił do stanu sprzed moich ostatnich zmian.',
  'Edit my answers': 'Edytuj moje odpowiedzi',
  'Start a new plan': 'Zacznij nowy plan',
  'A fresh plan from your answers; your workouts stay': 'Nowy plan na podstawie twoich odpowiedzi; treningi zostają',
  'Build me a fresh plan from my answers.': 'Ułóż mi nowy plan na podstawie moich odpowiedzi.',
  'Experience': 'Doświadczenie',
  'Goal, days, equipment, limits': 'Cel, dni, sprzęt, ograniczenia',
  'Have a look at my training and tell me what you would change.': 'Przejrzyj mój trening i powiedz, co warto zmienić.',
  'Here is what I am working with:': 'Oto, z czym pracuję:',
  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': 'Cześć, jestem twoim Trenerem. Buduję plan z twoich odpowiedzi i dostosowuję go do tego, co naprawdę zapisujesz. Nic się nie zmieni, dopóki nie powiesz.',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': 'Przejrzałem wszystko i na razie niczego bym nie zmieniał. Tak trzymaj i zapytaj mnie znów po kilku kolejnych sesjach.',
  'I understand, let’s go': 'Rozumiem, zaczynamy',
  'Imported! {0} routines are in your plan and your week is set. See you at the next session.': { one: 'Zaimportowano {0} plan treningowy, a tydzień jest ustawiony. Do zobaczenia na następnym treningu.', few: 'Zaimportowano {0} plany treningowe, a tydzień jest ustawiony. Do zobaczenia na następnym treningu.', many: 'Zaimportowano {0} planów treningowych, a tydzień jest ustawiony. Do zobaczenia na następnym treningu.', other: 'Zaimportowano {0} planów treningowych, a tydzień jest ustawiony. Do zobaczenia na następnym treningu.' },
  'Imported! {0} routines are in your plan. Your week is unchanged; schedule them whenever you like.': { one: 'Zaimportowano {0} plan treningowy. Tydzień bez zmian; zaplanuj je, kiedy chcesz.', few: 'Zaimportowano {0} plany treningowe. Tydzień bez zmian; zaplanuj je, kiedy chcesz.', many: 'Zaimportowano {0} planów treningowych. Tydzień bez zmian; zaplanuj je, kiedy chcesz.', other: 'Zaimportowano {0} planów treningowych. Tydzień bez zmian; zaplanuj je, kiedy chcesz.' },
  'It designs your plan from a few answers and adjusts it from what you actually log. It never changes anything without your say-so, and you can undo every change.': 'Projektuje plan z kilku odpowiedzi i dostosowuje go do tego, co naprawdę zapisujesz. Nigdy nic nie zmienia bez twojej zgody, a każdą zmianę możesz cofnąć.',
  'Routines, exercises, sets and reps, your weekly schedule and progression settings.': 'Rutyny, ćwiczenia, serie i powtórzenia, Twój harmonogram tygodnia i ustawienia progresji.',
  'Your logged training': 'Twój zapisany trening',
  'Sets you logged in the review window: weights, reps, times, effort ratings, how long sessions took, and your session notes.': 'Serie zapisane w okresie przeglądu: ciężary, powtórzenia, czasy, oceny wysiłku, długość sesji i Twoje notatki do sesji.',
  'Weigh-ins from the same window, and your goal weight if you set one.': 'Ważenia z tego samego okresu i Twoja docelowa waga, jeśli jest ustawiona.',
  'What you tell the Coach': 'Co mówisz Trenerowi',
  'Your intake answers, including any limitations or injuries you describe.': 'Twoje odpowiedzi z ankiety, w tym ograniczenia lub kontuzje, które opisujesz.',
  'A few preferences': 'Kilka ustawień',
  'Your unit, your language and which effort scale you log.': 'Twoja jednostka, Twój język i skala, w której oceniasz wysiłek.',
