  '{0} minutes is long. Rest periods may be creeping up.': { one: '{0} minuta to długo. Przerwy mogą się wydłużać.', few: '{0} minuty to długo. Przerwy mogą się wydłużać.', many: '{0} minut to długo. Przerwy mogą się wydłużać.', other: '{0} minut to długo. Przerwy mogą się wydłużać.' },
  'Top sets logged without an effort rating; add RIR so the next review can read how hard they were.': 'Główne serie bez oceny wysiłku; dodaj RIR, żeby następny przegląd wiedział, jak były ciężkie.',
