  'Keep the session under an hour and a quarter.': 'Trzymaj sesję poniżej godziny i kwadransa.',
  'A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.': 'Czysta sesja: wszystko z planu zrobione, ciężary utrzymane. Tak właśnie wygląda postęp od środka: niepozornie i powtarzalnie.',
