  'Base weight ({0})': 'Ciężar bazowy ({0})',
  'The machine or sled itself, before any plate goes on. 0 if it is all plates.': 'Sama maszyna lub sanie, zanim dołożysz jakikolwiek talerz. 0, jeśli to same talerze.',
  'Plates': 'Talerze',
  'Pairs of each size you own. Every set row loads from this list, so a home gym with one pair of 45s is never told to use two.': 'Pary każdego rozmiaru, jakie masz. Każdy wiersz serii ładuje się z tej listy, więc domowa siłownia z jedną parą 45-tek nigdy nie usłyszy, żeby użyć dwóch.',
  'pairs': 'par',
  'Your own list for {0}.': 'Twoja własna lista dla {0}.',
  'The standard set, plenty of each. Change any count to make it yours.': 'Standardowy zestaw, każdego rozmiaru pod dostatkiem. Zmień dowolną liczbę, aby był twój.',
  'Back to the standard set': 'Wróć do standardowego zestawu',
  'Standard set. Tap to count the pairs you own.': 'Standardowy zestaw. Dotknij, aby policzyć swoje pary.',
  'You still log the total weight. This only feeds the plate line under each set.': 'Nadal zapisujesz ciężar całkowity. To służy tylko linii z talerzami pod każdą serią.',
  'Default for this bar type.': 'Wartość domyślna dla tego typu gryfu.',
  'No bar': 'Bez gryfu',
  'The weight you log is all plates.': 'Zapisany ciężar to same talerze.',
  'Plates are counted from 0. Turn this off for the default ({0}).': 'Talerze liczone od 0. Wyłącz, aby wrócić do domyślnego ({0}).',
  'Set to 0 to go back to the default ({0}).': 'Ustaw 0, aby wrócić do wartości domyślnej ({0}).',
  'Applies to this exercise everywhere, not just this plan.': 'Dotyczy tego ćwiczenia wszędzie, nie tylko w tym planie.',
