  'Add this device\'s workouts to your profile?': 'Dodać treningi z tego urządzenia do profilu?',
  '{0} workouts and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tym urządzeniu bez logowania zapisano treningi ({0}) i ważenia ({1}). Dodaj je do profilu albo zostaw profil dokładnie taki, jaki jest na serwerze.',
  '{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tym urządzeniu bez logowania zapisano treningi ({0}) i ważenia ({1}). Dodaj je do profilu albo zostaw profil dokładnie taki, jaki jest na serwerze.',
  '{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tym urządzeniu bez logowania zapisano treningi ({0}) i ważenia ({1}). Dodaj je do profilu albo zostaw profil dokładnie taki, jaki jest na serwerze.',
  '{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': 'Na tym urządzeniu bez logowania zapisano treningi ({0}) i ważenia ({1}). Dodaj je do profilu albo zostaw profil dokładnie taki, jaki jest na serwerze.',
