  'Your server no longer accepts this browser. Your changes are kept here.': 'Twój serwer nie akceptuje już tej przeglądarki. Twoje zmiany zostają tutaj.',
  'This phone is no longer paired with your server. Your changes are kept here.': 'Ten telefon nie jest już sparowany z twoim serwerem. Twoje zmiany zostają tutaj.',
  'The server refuses this phone': 'Serwer odrzuca ten telefon',
  'Your server no longer accepts this phone. Your changes are kept here.': 'Twój serwer nie akceptuje już tego telefonu. Twoje zmiany zostają tutaj.',
