  'Not on your server yet: {0}': 'Jeszcze nie na twoim serwerze: {0}',
  'Some changes on this device have not reached your server.': 'Niektóre zmiany z tego urządzenia nie dotarły jeszcze na twój serwer.',
  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Spróbuj ponownie albo najpierw wyeksportuj kopię. Jeśli mimo to przejdziesz dalej, kopia tych zmian zostanie na tym urządzeniu, aż ponownie połączy się z tym serwerem na tym koncie. Wtedy zostaną dodane z powrotem.',
  'Syncing…': 'Synchronizowanie…',
  'Try again': 'Spróbuj ponownie',
  'Last synced: {0}': 'Ostatnia synchronizacja: {0}',
  'Not synced with this server yet': 'Jeszcze nie zsynchronizowano z tym serwerem',
  'Server & sync': 'Serwer i synchronizacja',
  'Signed in as {0}': 'Zalogowano jako {0}',
  'Sync now': 'Synchronizuj teraz',
  'Your changes are kept here, and merged into your account once it is paired again.': 'Twoje zmiany zostają tutaj i zostaną scalone z twoim kontem, gdy telefon zostanie ponownie sparowany.',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'Twoje zmiany zostają tutaj i zostaną scalone z twoim kontem, gdy znów się zalogujesz.',
  'Changes kept for {0}': 'Zmiany zachowane dla {0}',
  'Added back when this device connects as that account again.': 'Zostaną dodane z powrotem, gdy to urządzenie znów połączy się z tym kontem.',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': 'Zmiany, których twój serwer jeszcze nie ma, zostają na tym urządzeniu i zostaną dodane z powrotem, gdy znów połączy się ono z tym kontem.',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': 'Ten telefon wraca do trybu lokalnego, a kopia twojego konta zostaje z niego usunięta. Najpierw sprawdzane jest, czy twój serwer ma wszystkie zmiany. Jeśli nie, sam decydujesz, co się z nimi stanie.',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': 'Twoje dane zostają usunięte z tej przeglądarki; twój profil na serwerze je zachowuje. Najpierw sprawdzane jest, czy serwer ma wszystkie zmiany. Jeśli nie, sam decydujesz, co się z nimi stanie.',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': 'Wylogowuje ten profil na wszystkich urządzeniach, także na tym. Sparowane z nim telefony zostaną rozłączone i trzeba je będzie sparować ponownie. Twoje klucze dostępu nadal działają, więc w każdej chwili możesz się nimi znów zalogować.',
  '{0} change': '{0} zmiana',
  '{0} changes': { one: '{0} zmiana', few: '{0} zmiany', many: '{0} zmian' },
  // --- plan vs session: the routine's own reps, per-routine progress (#275, #216) ---
  'Default progression': 'Domyślna progresja',
  'Planned sessions start from': 'Punkt wyjścia zaplanowanych treningów',
  'The routine’s sets and reps. Your history decides the weight.': 'Serie i powtórzenia z planu treningowego. Ciężar wynika z twojej historii.',
  'Your last session': 'Twoja ostatnia sesja',
  'The reps you logged last time in that routine, carried over, and any warm-ups you set up yourself. With progression off, the weight too.': 'Powtórzenia z ostatniego razu w tej rutynie są przenoszone, razem z rozgrzewkami ustawionymi przez ciebie. Przy wyłączonej progresji także ciężar.',
  'Last time means': '„Ostatnio” oznacza',
  'This routine': 'Ten plan treningowy',
  'Your last session of the exercise in the same routine. Heavy day and light day stay apart.': 'Twoja ostatnia sesja ćwiczenia w tym samym planie treningowym. Ciężki i lekki dzień liczą się osobno.',
  'Any workout': 'Dowolny trening',
  'The last time you did the exercise, whichever routine it was in.': 'Ostatni raz, kiedy robiłeś to ćwiczenie, w jakimkolwiek planie.',
  'Plan changed, so starting from your new target.': 'Plan się zmienił, więc zaczynasz od nowego celu.',
  'First time in this routine, so starting from its own target.': 'Pierwszy raz w tym planie treningowym, więc zaczynasz od jego własnego celu.',
  'No weight logged last time. Enter what you lift and progression takes it from there.': 'Ostatnio nie zapisano ciężaru. Wpisz, ile podnosisz, a progresja ruszy od tego miejsca.',
  'Plan: {0}': 'Plan: {0}',
  'today {0}': 'dziś {0}',
