  'Create an independent routine from these exercise targets. Your workout history is kept.': 'Utwórz niezależny plan treningowy z tych celów ćwiczeń. Historia treningów pozostanie bez zmian.',
  'Pause': 'Wstrzymaj',
  'Keep timing after target': 'Kontynuuj pomiar po czasie docelowym',
  'Timed sets continue up to 15 extra minutes. Tap Done to log the actual duration.': 'Serie na czas trwają do 15 dodatkowych minut. Dotknij Gotowe, aby zapisać rzeczywisty czas.',
  'Edit workout': 'Edytuj trening',
  'Workout updated': 'Trening zaktualizowany',
  'Save workout changes?': 'Zapisać zmiany treningu?',
  'Save your edits to this workout, or keep the original record.': 'Zapisz zmiany w tym treningu albo zachowaj oryginalny zapis.',
  'Save changes': 'Zapisz zmiany',
  "Don't save": 'Nie zapisuj',
  'Keep editing': 'Kontynuuj edycję',
  'This workout was deleted on another device. Your edits are still here.': 'Ten trening usunięto na innym urządzeniu. Twoje zmiany nadal są tutaj.',
  'Close editor': 'Zamknij edytor',
  'Editing a saved workout. Date and duration stay unchanged.': 'Edytujesz zapisany trening. Data i czas trwania pozostaną bez zmian.',
  // --- demo build (v1.3.7) ---
  'A pull for every press, so the shoulders stay balanced.': 'Na każde wyciskanie jedno przyciąganie, żeby barki pozostały w równowadze.',
  'A two-day rotation across three sessions a week, built around the equipment you listed. Compounds first, one pull for every press, and enough overlap between the days that nothing goes two weeks without being trained.': 'Dwudniowa rotacja na trzy sesje w tygodniu, zbudowana wokół wskazanego przez ciebie sprzętu. Najpierw ćwiczenia wielostawowe, na każde wyciskanie jedno przyciąganie i na tyle dużo wspólnego między dniami, żeby nic nie zostało bez treningu przez dwa tygodnie.',
  'Based on the training already in this demo profile.': 'Na podstawie treningów, które już są w tym profilu demo.',
  'Body weight has been flat for four weeks while the goal is to gain. That’s a kitchen problem, not a training one. The plan isn’t what’s holding it back.': 'Masa ciała stoi w miejscu od czterech tygodni, a celem jest przybranie na wadze. To problem kuchni, a nie treningu. To nie plan ją hamuje.',
  'Demo': 'Demo',
  'Demo data reset': 'Dane demo zresetowane',
  'Direct arm work, since you asked for it.': 'Bezpośrednia praca na ramiona, zgodnie z twoją prośbą.',
  'Every top set on this one came in at RPE 9.5 or above for three sessions and the weight has not moved. Swapping the movement for four weeks usually breaks that stall faster than grinding the same one.': 'Każda główna seria w tym ćwiczeniu przez trzy sesje wypadała na RPE 9,5 lub wyżej, a ciężar się nie ruszył. Zmiana ruchu na cztery tygodnie zwykle szybciej przełamuje taki zastój niż mozolenie się z tym samym.',
  'Example data, stored only in this browser. Go wild and change anything you like.': 'Przykładowe dane, zapisane tylko w tej przeglądarce. Szalej i zmieniaj, co chcesz.',
  'Full body A': 'Całe ciało A',
  'Full body B': 'Całe ciało B',
  'Horizontal pressing, the other half of the session.': 'Wyciskanie poziome, druga połowa sesji.',
  'Live demo. Everything stays in this browser.': 'Demo na żywo. Wszystko zostaje w tej przeglądarce.',
  'No training history yet, so starting conservatively.': 'Brak historii treningów, więc zaczynamy ostrożnie.',
  'Passkey sign-in, sync across your devices, your own data.': 'Logowanie kluczem dostępu, synchronizacja między twoimi urządzeniami, twoje własne dane.',
  'Puts the example plan, workouts and weigh-ins back the way they started.': 'Przywraca przykładowy plan, treningi i ważenia do stanu początkowego.',
  'Reset': 'Resetuj',
  'Reset demo data': 'Zresetuj dane demo',
  'Reset demo data?': 'Zresetować dane demo?',
  'Revised as you asked. Everything you did not question is exactly as it was.': 'Poprawione zgodnie z prośbą. Wszystko, czego nie kwestionowano, zostało dokładnie tak, jak było.',
  'Same pattern, higher reps than day A.': 'Ten sam wzorzec, więcej powtórzeń niż w dniu A.',
  'Self-host it in a minute →': 'Postaw go u siebie w minutę →',
  'Self-host openGym': 'Postaw openGym u siebie',
  'Sessions have been running about fifteen minutes over. This is the accessory with the least to lose from one set fewer.': 'Sesje trwają około piętnastu minut za długo. To ćwiczenie akcesoryjne straci najmniej na jednej serii mniej.',
  'Start the demo': 'Uruchom demo',
  'The main lower-body driver, where most of the strength comes from.': 'Główny motor dolnej części ciała, stąd bierze się większość siły.',
  'The same patterns, different variations: enough overlap to progress, enough difference to stay fresh.': 'Te same wzorce, inne warianty: wystarczająco wspólnego, by robić postępy, i wystarczająco różnic, by się nie nudzić.',
  'The two big lower-body and pressing patterns first, while you are fresh.': 'Najpierw dwa duże wzorce: nogi i wyciskanie, póki masz świeże siły.',
  'This demo runs entirely in your browser on example data. Nothing is sent anywhere. Passkey sign-in and sync across your devices come with the openGym server, which you get by self-hosting it.': 'To demo działa w całości w twojej przeglądarce na przykładowych danych. Nic nie jest nigdzie wysyłane. Logowanie kluczem dostępu i synchronizacja między urządzeniami przychodzą z serwerem openGym, który dostajesz, hostując go samodzielnie.',
  'Three things worth changing, and one worth knowing about. Everything else is working: the squat and the pulls are both progressing on schedule.': 'Trzy rzeczy warte zmiany i jedna warta uwagi. Cała reszta działa: przysiad i przyciągania postępują zgodnie z planem.',
  'Vertical pressing.': 'Wyciskanie pionowe.',
  'You have moved this session to Saturday three weeks running. Better the plan says so than that you keep overriding it.': 'Od trzech tygodni z rzędu przenosisz tę sesję na sobotę. Lepiej, żeby plan to uwzględniał, niż ciągle go nadpisywać.',
  'You’re in the demo': 'Jesteś w wersji demo',
