  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': 'Żeby odpowiedzieć, Trener wysyła to przez twój serwer openGym do {0}, usługi AI spoza openGym wybranej przez admina twojego serwera:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'Żeby odpowiedzieć, to urządzenie wysyła to bezpośrednio do {0}, usługi AI spoza openGym, z twoim kluczem API:',
  'Who may see your training': 'Kto może widzieć twój trening',
