  // --- Settings → Apple Watch ---
  'Apple Watch': 'Apple Watch',
  'Weight': 'Ciężar',
  'Send workouts to the watch': 'Wysyłaj treningi na zegarek',
  'Open on the watch': 'Otwórz na zegarku',
  'Start a workout on the phone and openGym pops up on your wrist.': 'Zacznij trening w telefonie, a openGym wyskoczy ci na nadgarstku.',
  'Not allowed': 'Brak zgody',
