  'Not allowed on the watch. Allow it in the Health app on your iPhone.': 'Brak zgody na zegarku. Zezwól w aplikacji Zdrowie na iPhonie.',
  'Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.': 'Tętno podczas treningu i przy każdej serii, a trening zapisany w Zdrowiu. Zegarek zapyta raz.',
  'Apple Health': 'Apple Zdrowie',
  'Write to Apple Health': 'Zapisuj w Apple Zdrowie',
  'Open Apple Health': 'Otwórz Apple Zdrowie',
  'Workouts and weigh-ins go to Apple Health when you finish or change them.': 'Treningi i pomiary wagi trafiają do Apple Zdrowie, gdy je kończysz lub zmieniasz.',
  'Writing to Apple Health': 'Zapisywanie w Apple Zdrowie',
  'Apple Health permission not granted': 'Nie przyznano uprawnienia Apple Zdrowie',
