  // --- reading back from Health Connect / Apple Health (v1.4.3) ---
  'Heart rate from your watch': 'Tętno z zegarka',
  'After a workout, each set gets the heart rate your watch saved. Garmin, Fitbit, Galaxy Watch and friends welcome.': 'Po treningu każda seria dostaje tętno zapisane przez zegarek. Garmin, Fitbit, Galaxy Watch i spółka mile widziani.',
  'Weigh-ins from other apps': 'Pomiary wagi z innych aplikacji',
  'Your smart scale’s weigh-ins land here. One you type in yourself always wins.': 'Pomiary z twojej inteligentnej wagi trafiają tutaj. Ten wpisany ręcznie zawsze wygrywa.',
  'openGym reads only while it is open: heart rate for workouts of the last day, weigh-ins of the last 30 days. Older workouts stay as they are.': 'openGym czyta tylko, gdy jest otwarty: tętno z treningów z ostatniej doby, pomiary wagi z ostatnich 30 dni. Starsze treningi zostają bez zmian.',
  // --- gym reminder (#614) ---
  'A nudge when you walk into your gym.': 'Szturchnięcie, gdy wchodzisz na siłownię.',
  'Add a gym': 'Dodaj siłownię',
  'All the time': 'Zezwalaj zawsze',
  'Allow location “All the time”?': 'Zezwolić na lokalizację „Zezwalaj zawsze”?',
  'Allow location “Always”?': 'Zezwolić na lokalizację „Zawsze”?',
  'Always': 'Zawsze',
  'Finding you…': 'Szukamy cię…',
  'Gym reminder': 'Przypomnienie na siłowni',
  'Checking if you made it to the gym': 'Sprawdzam, czy dotarłeś na siłownię',
  'Quick arrival check': 'Szybkie wykrycie przyjścia',
  'Near a gym, the phone takes a short GPS look (a few minutes at most) so the nudge comes at the door.': 'W pobliżu siłowni telefon na chwilę zerka na GPS (najwyżej kilka minut), żeby przypomnienie przyszło już przy drzwiach.',
  'Android can take up to half an hour to notice you walked in. Set openGym’s battery use to Unrestricted and the phone takes a short GPS look when you get near a gym, so the nudge comes at the door.': 'Android potrafi zauważyć twoje przyjście nawet po pół godzinie. Ustaw zużycie baterii openGym na Bez ograniczeń, a telefon w pobliżu siłowni na chwilę zerknie na GPS i przypomnienie przyjdzie przy drzwiach.',
  'Gym spotted': 'Siłownia namierzona',
  'Leave it empty for the default.': 'Zostaw puste dla domyślnego tekstu.',
  'Location access': 'Dostęp do lokalizacji',
  'Location isn’t allowed for openGym. You can change that in the phone’s settings.': 'openGym nie ma dostępu do lokalizacji. Możesz to zmienić w ustawieniach telefonu.',
  'My gym': 'Moja siłownia',
  'Name': 'Nazwa',
  'No more nudges when you arrive here.': 'Koniec szturchnięć, gdy tu przychodzisz.',
  'Not asked yet': 'Jeszcze nie pytano',
