  'Notification text': 'Tekst powiadomienia',
  'Notifications are off for openGym, so the reminder has nowhere to show up.': 'Powiadomienia openGym są wyłączone, więc przypomnienie nie ma gdzie się pokazać.',
  'On the next screen, pick “Allow all the time”.': 'Na następnym ekranie wybierz „Zezwalaj zawsze”.',
  'Only between certain hours': 'Tylko w określonych godzinach',
  'Only while using the app': 'Tylko podczas używania aplikacji',
  'Outside these hours the phone stays quiet, even at the gym.': 'Poza tymi godzinami telefon milczy, nawet na siłowni.',
  'Radius': 'Promień',
  'Ready for your workout? 💪': 'Gotowy na trening? 💪',
  'Remove this gym?': 'Usunąć tę siłownię?',
  'Search': 'Szukaj',
  'Searching…': 'Szukam…',
  'That’s 20 gyms, the most a phone can watch.': 'To już 20 siłowni, więcej telefon nie upilnuje.',
  'The phone itself watches the gyms you added and only wakes openGym when you arrive. No tracking in between, and your locations never leave this phone.': 'Telefon sam pilnuje dodanych siłowni i budzi openGym dopiero, gdy dotrzesz. Żadnego śledzenia pomiędzy, a twoje miejsca nigdy nie opuszczają tego telefonu.',
  'The reminder needs location access in the background. You can allow it in the phone’s settings.': 'Przypomnienie potrzebuje lokalizacji w tle. Możesz na nią zezwolić w ustawieniach telefonu.',
  'To notice that you walked into your gym while openGym is closed, the phone needs to let it see your location in the background.': 'Żeby zauważyć, że wszedłeś na siłownię, gdy openGym jest zamknięty, telefon musi pozwolić mu widzieć twoją lokalizację w tle.',
  'Until': 'Do',
  'Walk into one of your gyms and openGym nudges you to hit Start. Once a day at most, and never when you already trained. Your gyms stay on this phone.': 'Wejdź na jedną ze swoich siłowni, a openGym szturchnie cię, żebyś nacisnął Start. Najwyżej raz dziennie i nigdy, gdy już trenowałeś. Twoje siłownie zostają na tym telefonie.',
  'Without background location the phone can’t spot your gym while openGym is closed.': 'Bez lokalizacji w tle telefon nie rozpozna siłowni, gdy openGym jest zamknięty.',
  'Your gyms': 'Twoje siłownie',
  '{0} m': '{0} m',
  'Precise location is off for openGym. Turn it on in the phone’s settings, or your gym can’t be spotted.': 'Dokładna lokalizacja jest wyłączona dla openGym. Włącz ją w ustawieniach telefonu, inaczej siłownia nie zostanie rozpoznana.',
