  'Each adds its own routines, so your plan stays as it is until you start it.': 'Każdy dodaje własne plany treningowe, więc twój plan zostaje bez zmian, dopóki go nie uruchomisz.',
  'Effort for the week': 'Wysiłek na tydzień',
  'Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.': 'Puste zostawia ciężar twojej progresji. %1RM liczy się z twojego najlepszego szacowanego 1RM.',
  'End programme': 'Zakończ program',
  'End “{0}”?': 'Zakończyć „{0}”?',
  'Four days. Your progression picks the weights, the effort climbs to RPE 9, then a deload.': 'Cztery dni. Progresja dobiera ciężary, wysiłek rośnie do RPE 9, potem deload.',
  'Heavier means every %1RM goes up {0} points.': 'Ciężej znaczy, że każdy %1RM rośnie o {0} pkt.',
  'It is running: ending it brings your plan back. Its routines stay.': 'Właśnie trwa: zakończenie przywraca twój plan. Plany treningowe zostają.',
  'Its routines stay.': 'Plany treningowe zostają.',
  'Its schedule takes over your plan until you end it. Then your plan comes back as it was.': 'Jego harmonogram zastępuje twój plan, dopóki go nie zakończysz. Potem plan wraca taki, jaki był.',
  'Lighter weights, and its sessions do not count toward progression.': 'Lżejsze ciężary, a treningi nie liczą się do progresji.',
