  // --- NFC stickers (components/Nfc.jsx) ---
  "Add {0}?": "Dodać {0}?",
  "Any blank NTAG sticker works. Writing replaces what was on it.": "Pasuje każda pusta naklejka NTAG. Zapis zastępuje to, co na niej było.",
  "Hold the back of your phone to the sticker.": "Przyłóż tył telefonu do naklejki.",
  "Hold the top of your iPhone near the sticker.": "Przyłóż górę iPhone’a do naklejki.",
  "It isn’t in this workout yet.": "Jeszcze go nie ma w tym treningu.",
  "Just check in": "Tylko zamelduj",
  "NFC is off. Turn it on in your phone’s settings and try again.": "NFC jest wyłączone. Włącz je w ustawieniach telefonu i spróbuj jeszcze raz.",
  "NFC sticker for this exercise": "Naklejka NFC dla tego ćwiczenia",
  "Put it on your locker, your bag or the gym door. One tap with your phone and you’re in.": "Przyklej ją na szafkę, torbę albo drzwi siłowni. Jedno dotknięcie telefonem i jesteś w środku.",
  "Set up an NFC sticker": "Skonfiguruj naklejkę NFC",
  "Shows your gym membership code, ready for the scanner.": "Pokazuje twój kod karnetu, gotowy do skanera.",
  "Start today’s workout": "Zacznij dzisiejszy trening",
  "Starts what’s planned for today, or opens the one already running.": "Zaczyna to, co zaplanowane na dziś, albo otwiera trwający trening.",
  "Stick it on the machine. Tap it during a workout to jump to {0}, or to add it.": "Przyklej ją na maszynę. Dotknij jej w trakcie treningu, żeby przejść do {0} albo je dodać.",
  "Sticker ready.": "Naklejka gotowa.",
  "Sticker ready. Tap it with your phone to try it.": "Naklejka gotowa. Dotknij jej telefonem, żeby wypróbować.",
  "Tap it at the gym to start your workout or show your code.": "Dotknij jej na siłowni, żeby zacząć trening albo pokazać kod.",
  "That didn’t work. Hold your phone still on the sticker and try again.": "Nie wyszło. Trzymaj telefon nieruchomo na naklejce i spróbuj jeszcze raz.",
  "This sticker can’t hold a link. Try an NTAG sticker.": "Ta naklejka nie zmieści linku. Spróbuj naklejki NTAG.",
  "This sticker is for an exercise you don’t have.": "Ta naklejka jest do ćwiczenia, którego nie masz.",
  "This sticker is locked. Try a blank one.": "Ta naklejka jest zablokowana. Spróbuj pustej.",
  "This sticker is too small. NTAG213 or bigger works.": "Ta naklejka jest za mała. NTAG213 lub większa wystarczy.",
